function jafloSummary(){
  // ---- defaults (estado parcial / app aun no inicializada) ----
  var out = { ICE:0, ICEmax:0, ace:0, aceMax:10, chrp:false, suicid:"No", factorP:"—", outcomes:[] };
  try {
    if (typeof computeScores !== "function" || typeof ITEMS === "undefined") return out;
    var sc = computeScores(); // {ice, nRisk, nProt, nCls1, nAns, buckets}

    // ICE real de la app (Σ pesos riesgo - Σ pesos protectores, redondeado a .1)
    out.ICE = (sc && typeof sc.ice === "number") ? sc.ice : 0;

    // ICEmax = techo teorico del ICE = Σ pesos de todos los items de riesgo (cada item 1 vez).
    // (OUTCOME_MAX NO sirve: duplica items con multiples outcomes.)
    var iceMax = 0;
    ITEMS.forEach(function(it){ if(it && it.direction !== "prot") iceMax += (it.weight || 0); });
    out.ICEmax = Math.round(iceMax * 10) / 10;

    // ---- ACE-10 (mismo conteo que el dashboard) ----
    var aceTotal = 0;
    if (typeof ACE_DIMS !== "undefined") {
      Object.keys(ACE_DIMS).forEach(function(d){
        (ACE_DIMS[d].ids || []).forEach(function(id){
          if (STATE && STATE.answers && STATE.answers[id] === "Sí") aceTotal++;
        });
      });
    }
    out.ace = aceTotal;
    out.aceMax = 10;

    // ---- CHR-P (igual que buildInstruments: E4-6 positivo) ----
    out.chrp = (typeof instPosCount === "function") ? (instPosCount(["E4-6"]) > 0) : false;

    // ---- Suicidalidad lifetime (escalera C-SSRS de buildInstruments) ----
    if (typeof instPosCount === "function") {
      if (instPosCount(["E2-12"]) > 0) out.suicid = "Intento";
      else if (instPosCount(["E2-11"]) > 0) out.suicid = "Ideación";
      else if (instPosCount(["E2-13"]) > 0) out.suicid = "NSSI";
      else out.suicid = "No";
    }

    // ---- Factor-p / espectro HiTOP dominante (mismas listas que renderGraphsHTML) ----
    if (typeof instPosCount === "function") {
      var ratio = function(ids){ return (ids && ids.length) ? instPosCount(ids)/ids.length : 0; };
      var spectra = [
        {nm:"Internalizante",       ids:["E2-3","E2-6","E2-7","E2-9","E2-11","E2-12","E2-13","E2-n1","E2-n3","E2-n6"]},
        {nm:"Psicosis (t. pensamiento)", ids:["E2-1","E2-2","E4-6"]},
        {nm:"Ext. desinhibido",     ids:["E2-5","E2-10","E2-n5"]},
        {nm:"Ext. antagónico",  ids:["E2-n4","E4-9"]},
        {nm:"Desapego",             ids:["E2-4","56","52"]}
      ];
      var best = null, bestVal = 0;
      spectra.forEach(function(s){ var v = ratio(s.ids); if (v > bestVal){ bestVal = v; best = s.nm; } });
      out.factorP = (best && bestVal > 0) ? best : "—";
    }

    // ---- outcomes[] = "riesgo de que" por condicion, pct 0-100 = saturacion (sat = risk/max) ----
    // misma fuente que las barras de "Carga por outcome" del dashboard.
    if (sc && sc.buckets && typeof OUTCOME_ORDER !== "undefined") {
      var arr = [];
      OUTCOME_ORDER.forEach(function(o){
        var b = sc.buckets[o];
        if (b) arr.push({ nm:o, pct: Math.round((b.sat || 0) * 100) });
      });
      arr.sort(function(a,b){ return b.pct - a.pct; });
      out.outcomes = arr;
    }
  } catch(e) { /* estado parcial: devolver lo que se haya podido calcular */ }
  return out;
}

