function jafloPrefill(id){
  id = id || {};
  try {
    // ---- helpers seguros ----
    var setSel = function(elId, val){
      var el = document.getElementById(elId);
      if (!el) return;
      if (val != null && val !== "") el.value = val;
      // espejo en STATE (la app persiste pAge/pSex/pGroup/pEval como STATE._<id>)
      if (typeof STATE !== "undefined") STATE["_" + elId] = el.value;
    };

    // ---- header de identidad ----
    // codigo -> #pName (campo "Paciente"; la app NO lo persiste, es de sesion)
    if (id.codigo != null) {
      var pn = document.getElementById("pName");
      if (pn) { pn.value = id.codigo; if (typeof STATE !== "undefined") STATE._pName = pn.value; }
    }
    if (id.edad != null) setSel("pAge", id.edad);
    if (id.evaluador != null) setSel("pEval", id.evaluador);

    // sexo -> #pSex (F / M / Otro). Solo label, NO toca scoring.
    var sx = (id.sexo || "").toString().trim().toUpperCase();
    var sexLabel = "";
    if (sx === "F" || sx === "FEMENINO" || sx === "MUJER") sexLabel = "F";
    else if (sx === "M" || sx === "MASCULINO" || sx === "HOMBRE" || sx === "VARON" || sx === "VARÓN") sexLabel = "M";
    else if (sx) sexLabel = "Otro";
    if (sexLabel) setSel("pSex", sexLabel);

    // grupo etario opcional: si llega ses/educacion no aplica aqui; #pGroup se deja
    // intacto salvo que se pueda inferir por edad (no requerido por el contrato).

    // ---- CRITICO: derivar items de scoring C-n1 / C-n2 desde id.sexo ----
    // La app NO captura el sexo como item; el scoring vive en C-n1 (Sexo femenino)
    // y C-n2 (Sexo masculino), ambos answerOptions ["Sí","No","NS"].
    if (typeof STATE !== "undefined") {
      if (!STATE.answers) STATE.answers = {};
      if (sexLabel === "F") { STATE.answers["C-n1"] = "Sí"; STATE.answers["C-n2"] = "No"; }
      else if (sexLabel === "M") { STATE.answers["C-n1"] = "No"; STATE.answers["C-n2"] = "Sí"; }
      else if (sexLabel === "Otro") { STATE.answers["C-n1"] = "NS"; STATE.answers["C-n2"] = "NS"; }
      // sexo ausente: no se tocan C-n1/C-n2 (preserva estado parcial)

      // persistir con la misma key de la app
      if (typeof save === "function") save();
    }

    // refrescar la UI de captura para reflejar C-n1/C-n2 y header
    if (typeof renderCapture === "function") renderCapture();
    if (typeof updateProgress === "function") updateProgress();

    // avisar al maestro que cambio el estado
    try { parent.postMessage({ type:"JAFLO_CHANGED", app:"exposoma" }, "*"); } catch(e){}
  } catch(e) { /* prefill robusto: no romper la app */ }
}

