function jafloSummary(){
  // Lee las funciones REALES de Exposome Functioning. Robusto a estado parcial.
  var out = { media: null, quadrant: '—', alarma: 0, patron: '' };
  try {
    // 1) media: media funcional actual 0(mejor)-6(peor) que la app ya calcula
    if (typeof currentMean === 'function') {
      var m = currentMean();           // null si la etapa actual no tiene celdas puntuadas
      out.media = (m === null || m === undefined || isNaN(m)) ? null : m;
    }
  } catch (e) {}

  try {
    // 2) quadrant: string del cuadrante exposomico (cruce funcion x exposicion Note 1)
    if (typeof exposomeReading === 'function') {
      var ex = exposomeReading();      // { mean, funcLevel, exp, verdict, explain }
      out.quadrant = (ex && ex.verdict) ? ex.verdict : '—';
    }
  } catch (e) {}

  try {
    // 3) alarma: nro de ejes (0-7) en alarma, usando el MISMO corte que exportClinical():
    //    eje en alarma si current>=3 (deterioro actual) o delta>=3 (caida pico->actual)
    var n = 0;
    if (typeof AXES !== 'undefined' && typeof axisTrajectory === 'function') {
      for (var i = 0; i < AXES.length; i++) {
        var tj = axisTrajectory(AXES[i].id);
        if (!tj) continue;
        var hit = (tj.current != null && tj.current >= 3) || (tj.delta != null && tj.delta >= 3);
        if (hit) n++;
      }
    }
    out.alarma = n;
  } catch (e) {}

  try {
    // 4) patron: string del patron narrativo McAdams (redentor|contaminante|mixto|agentico|comunal)
    if (typeof narr === 'function') {
      var N = narr();
      out.patron = (N && N.pattern) ? N.pattern : '';
    }
  } catch (e) {}

  return out;
}

