function jafloPrefill(id){
  // App Exposome Functioning: solo id.edad participa en scoring (activa etapas de vida).
  // id.sexo NO se usa aqui (no hay campo de sexo en esta app); se ignora salvo display futuro.
  try {
    if (id && id.edad !== undefined && id.edad !== null && id.edad !== '') {
      var n = parseInt(id.edad, 10);
      if (!isNaN(n)) {
        // setAge() es el setter canonico: setea state.age, persiste y re-renderiza,
        // lo que activa automaticamente las etapas (STAGES) que dependen de la edad.
        if (typeof setAge === 'function') {
          setAge(n);
        } else if (typeof state !== 'undefined') {
          state.age = n;
          if (typeof saveState === 'function') saveState();
          if (typeof renderScoreView === 'function') renderScoreView();
        }
        // Reflejo defensivo en el DOM por si el re-render no recreo el input aun.
        var el = document.getElementById('ageInput');
        if (el) el.value = String(n);
      }
    }
  } catch (e) {}
  // id.sexo: sin campo en esta app -> no-op intencional.
}

