function jafloSummary(){
  // Lee el estado REAL de la app exp_hist desde localStorage (key 'expHistApp_v2').
  // Forma del estado: {fields:{}, multi:{}, single:{}, episodes:[]}
  var st={fields:{},multi:{},single:{},episodes:[]};
  try{
    // Preferir el objeto 'state' vivo si la app esta cargada; si no, leer localStorage.
    if(typeof state==='object'&&state&&state.single){ st=state; }
    else{ var raw=localStorage.getItem('expHistApp_v2'); if(raw){ var d=JSON.parse(raw); if(d) st=Object.assign(st,d); } }
  }catch(e){}
  var s=st.single||{}, eps=Array.isArray(st.episodes)?st.episodes:[];

  // --- curso: valor real del chip-group data-single="curso" ---
  // Posibles: 'primer contacto','episódico-recurrente','episodio único','continuo','fluctuante','progresivo'
  var cursoRaw=s.curso||'';
  // Normaliza a forma ascii con guiones (estilo del contrato: 'episodico-recurrente')
  var curso=cursoRaw
    .normalize('NFD').replace(/[̀-ͯ]/g,'') // quita acentos
    .trim().toLowerCase().replace(/\s+/g,'-');
  // curso='' si el paciente aun no lo eligio

  // --- episodios: cuenta periodos NO vacios (mismo filtro que generate()) ---
  var episodios=eps.filter(function(e){
    return e && Object.values(e).some(function(v){ return v && String(v).trim(); });
  }).length;
  // Si marco 'sin trayectoria previa / primer contacto', episodios efectivos = 0
  if(s.primer==='si') episodios=0;

  // --- safety: NO existe funcion safety-gate explicita en la app.
  // Se DERIVA del bloque "Estado de seguridad AL MOMENTO" + conductas de riesgo.
  // 'fail'  = riesgo agudo alto (vector suicida completo, intento+metodo violento, o heteroagresividad activa)
  // 'warn'  = senal de riesgo presente pero no critica
  // 'g'     = sin senales de riesgo agudo
  var cri=Array.isArray(st.multi&&st.multi.cri)?st.multi.cri:[];
  var hasIntento = cri.indexOf('intento suicida')>=0;
  var hasViolencia = cri.indexOf('violencia')>=0;
  var ideacionActiva = s.ideacionActiva==='activa';
  var ideacionPasiva = s.ideacionActiva==='pasiva';
  var plan = s.plan==='sí'||s.plan==='si';
  var intencion = s.intencion==='sí'||s.intencion==='si';
  var terceros = s.riesgoTerceros==='sí'||s.riesgoTerceros==='si';
  var desinhib = s.desinhibicion==='sí'||s.desinhibicion==='si';
  var metodoViolento = s.metodoViolento==='violento';

  var safety='g';
  // fail: vector suicida activo robusto, intento con metodo violento, o heteroagresividad
  if( (ideacionActiva && (plan||intencion)) ||
      (hasIntento && metodoViolento) ||
      (terceros) ||
      (hasViolencia) ){
    safety='fail';
  } else if( ideacionActiva || plan || intencion || ideacionPasiva ||
             hasIntento || desinhib ||
             (cri.length>0 && cri.indexOf('ninguna')<0) ){
    safety='warn';
  }

  return { curso:curso, episodios:episodios, safety:safety };
}

apps.vemmfalFnSource:
function jafloVemmfal(){
  // Senales auto que exp_hist SI posee, derivadas del estado real (key 'expHistApp_v2').
  var st={fields:{},multi:{},single:{},episodes:[]};
  try{
    if(typeof state==='object'&&state&&state.single){ st=state; }
    else{ var raw=localStorage.getItem('expHistApp_v2'); if(raw){ var d=JSON.parse(raw); if(d) st=Object.assign(st,d); } }
  }catch(e){}
  var f=st.fields||{}, s=st.single||{}, eps=Array.isArray(st.episodes)?st.episodes:[];
  var nonEmptyEps=eps.filter(function(e){ return e && Object.values(e).some(function(v){return v&&String(v).trim();}); });

  // ---- helpers de tiempo/duracion sobre texto libre ----
  function dur(txt){ return (txt||'').toString().toLowerCase(); }
  var dProd=dur(f.duracionProdromo), dDesde=dur(f.cursoDesde);
  function isHoursToWeek(t){
    // hiperagudo: horas hasta ~1 semana
    if(/\bhora|\bhrs?\b|\bd[ií]a/.test(t)) return true;
    var m=t.match(/(\d+)\s*sem/);
    if(m && parseInt(m[1],10)<=1) return true;
    if(/\buna?\s+sem/.test(t)) return true;
    return false;
  }
  function isProlongedProdrome(t){
    // pródromo >3 meses
    if(/a[ñn]os?|desde\s+(?:siempre|la\s+(?:adolescencia|infancia)|los?)/.test(t)) return true;
    var mm=t.match(/(\d+)\s*mes/); if(mm && parseInt(mm[1],10)>3) return true;
    var ms=t.match(/(\d+)\s*sem/); if(ms && parseInt(ms[1],10)>12) return true;
    var ya=t.match(/(\d+)\s*a[ñn]/); if(ya) return true;
    return false;
  }

  // ---- 1) Tempo hiperagudo (horas–~1 sem) ----
  // Inicio brusco + (duracion corta declarada O precipitante claro)
  var tempoHiperagudo = (s.inicioModo==='brusco') &&
    ( isHoursToWeek(dProd) || isHoursToWeek(dDesde) || s.tipoCambio==='precipitante claro' );

  // ---- 2) Síntomas de novo / 1.er episodio ----
  var deNovo = (s.curso==='primer contacto') || (s.curso==='episodio único') ||
               (s.primer==='si') || (nonEmptyEps.length<=1 && (s.curso==='primer contacto'||s.curso==='episodio único'));

  // ---- 3) Refractariedad a tratamiento psiquiátrico ----
  // Tratado, con adherencia buena, y recaida/respuesta pobre a traves de episodios.
  var ttoTxt=(f.tto||'').toLowerCase();
  var fueTratado = !!ttoTxt && !/nunca\s+tratad|sin\s+tratamiento|ninguno/.test(ttoTxt);
  var adherenciaBuena = s.adherencia==='buena';
  var respuestaPobre = nonEmptyEps.some(function(e){
    var r=(e.respuesta||'').toLowerCase(); return r==='no'||/parcial/.test(r);
  });
  var refractariedad = fueTratado && adherenciaBuena && respuestaPobre && nonEmptyEps.length>=1;

  // ---- 4) Insidioso con pródromo >3 meses (protector) ----
  var insidiosoProlongado = (s.inicioModo==='insidioso') &&
    ( isProlongedProdrome(dProd) || isProlongedProdrome(dDesde) );

  // ---- 5) Presentación similar a previos (protector) ----
  // Curso recurrente/continuo y >=2 periodos previos (hay historia para comparar)
  var similarPrevios = (nonEmptyEps.length>=2) &&
    (s.curso==='episódico-recurrente' || s.curso==='continuo' || s.curso==='fluctuante' || s.primer!=='si');

  // ---- 6) Edad de inicio >40 a (de la EDAD DE INICIO real, NO la edad actual) ----
  // Edad de inicio se extrae de cursoDesde ('desde los 38'), o del 'cuando' del 1er periodo.
  function edadInicio(){
    var cand=[];
    var src1=(f.cursoDesde||'');
    var m1=src1.match(/(?:desde\s+los?\s+|a\s+los?\s+)(\d{1,2})/i) || src1.match(/(\d{1,2})\s*a(?:ñ|n)?o?s?\b/i);
    if(m1) cand.push(parseInt(m1[1],10));
    if(nonEmptyEps.length){
      var c0=(nonEmptyEps[0].cuando||'');
      var m2=c0.match(/(?:los?\s+)?(\d{1,2})\s*a\b/i) || c0.match(/(\d{1,2})\s*a(?:ñ|n)?os?/i);
      if(m2) cand.push(parseInt(m2[1],10));
    }
    cand=cand.filter(function(n){ return !isNaN(n)&&n>0&&n<120; });
    return cand.length? Math.min.apply(null,cand) : null;
  }
  var ei=edadInicio();
  var inicioTardio = (ei!=null) && (ei>40);

  return {
    'Tempo hiperagudo (horas–~1 sem)': !!tempoHiperagudo,
    'Síntomas de novo / 1.er episodio': !!deNovo,
    'Refractariedad a tratamiento psiquiátrico': !!refractariedad,
    'Insidioso con pródromo >3 meses (protector)': !!insidiosoProlongado,
    'Presentación similar a previos (protector)': !!similarPrevios,
    'Edad de inicio >40 a': !!inicioTardio
  };
}

apps.prefillFnSource:
function jafloPrefill(id){
  // El shell envia identidad; exp_hist solo usa codigo/edad/fecha/evaluador (campos data-k).
  // sexo/educacion/ses/etc no tienen campo en esta app: se ignoran (no se inventan campos).
  if(!id) return;
  try{
    // Carga el estado actual para no pisar lo que el usuario ya escribio en otros campos.
    var st={fields:{},multi:{},single:{},episodes:[]};
    try{ var raw=localStorage.getItem('expHistApp_v2'); if(raw){ var d=JSON.parse(raw); if(d) st=Object.assign(st,d); } }catch(e){}
    if(typeof state==='object'&&state&&state.fields) st=state; // usar estado vivo si existe

    var map={ codigo:id.codigo, edad:id.edad, fecha:id.fecha, evaluador:id.evaluador };
    Object.keys(map).forEach(function(k){
      var v=map[k];
      if(v===undefined||v===null||v==='') return;
      st.fields=st.fields||{};
      st.fields[k]=String(v);
      // Refleja en el DOM y dispara el evento 'input' que la app escucha (bindFields()).
      var el=document.querySelector('[data-k="'+k+'"]');
      if(el){ el.value=String(v); el.dispatchEvent(new Event('input',{bubbles:true})); }
    });

    // Persistir con la MISMA key por si la app aun no ligo el input.
    try{ localStorage.setItem('expHistApp_v2', JSON.stringify(st)); }catch(e){}

    // Refrescar progreso si la funcion existe.
    try{ if(typeof updateProgress==='function') updateProgress(); }catch(e){}

    // Notificar al maestro que algo cambio.
    try{ parent.postMessage({type:'JAFLO_CHANGED', app:'exp_hist'}, '*'); }catch(e){}
  }catch(e){}
}

