function jafloSummary(){
  var DEF = { concienciaScore:0, macro:'', meso:'', micro:'', r:0, severidad:'',
              st3:'g', psp:'g', rdoc:[], hitop:[] };
  try {
    var st = (typeof state !== 'undefined' && state) ? state : {};

    // ── concienciaScore: NC.conciencia raw score (0 = preservada) ──
    var ncv = (st['NC.conciencia'] && st['NC.conciencia'].score);
    var conciencia = 0;
    if (ncv !== null && ncv !== undefined && ncv !== 'NE') {
      var n = parseInt(ncv, 10);
      conciencia = Number.isNaN(n) ? 0 : n;
    }
    DEF.concienciaScore = conciencia;

    // ── Fenotipo: motor real (matchPhenotype) + taxonomia latente PMC del dashboard ──
    if (typeof buildPhenotypeVector === 'function' && typeof matchPhenotype === 'function' && typeof PHENO !== 'undefined') {
      var vec = buildPhenotypeVector();
      var opts = (typeof NORM !== 'undefined') ? { norm: NORM } : {};
      var res = matchPhenotype(vec, PHENO, opts);
      if (res && res.confianza !== 'insuficiente' && res.macro && res.meso) {
        // El dashboard prefiere la capa latente real (bmseLatentTaxonomyProfile) cuando existe
        var lat = (typeof bmseLatentTaxonomyProfile === 'function') ? bmseLatentTaxonomyProfile(vec) : null;
        DEF.macro = (lat && lat.macro && lat.macro.label) ? lat.macro.label : (res.macro.label || '');
        DEF.meso  = (lat && lat.mesosTop && lat.mesosTop.length) ? lat.mesosTop[0].label : (res.meso.label || '');
        DEF.micro = (lat && lat.microsTop && lat.microsTop.length) ? lat.microsTop[0].label : (res.micro ? res.micro.label : '');
        // r del fenotipo: r del espectro (meso) ganador del motor real
        DEF.r = (res.meso && typeof res.meso.r === 'number') ? res.meso.r
              : (res.micro && typeof res.micro.r === 'number' ? res.micro.r : 0);
        // severidad: nota textual del p-factor
        DEF.severidad = (res.severidad && res.severidad.nota) ? res.severidad.nota : '';
      }
    }

    // ── 3ST suicidio: outcomeSuicidio().status -> g|warn|fail ──
    var mapStatus = function(s){
      if (s === 'red') return 'fail';
      if (s === 'yellow') return 'warn';
      return 'g'; // green / muted / desconocido
    };
    if (typeof outcomeSuicidio === 'function') {
      try { var su = outcomeSuicidio(); DEF.st3 = mapStatus(su && su.status); } catch(e){}
    }

    // ── PSP funcional: outcomeFuncionalidad().status -> g|warn|fail ──
    if (typeof outcomeFuncionalidad === 'function') {
      try { var fu = outcomeFuncionalidad(); DEF.psp = mapStatus(fu && fu.status); } catch(e){}
    }

    // ── RDoC constructos + HiTOP subfactores: arrays {nm,sub,dir,lv} ──
    var levelOf = function(pct){
      if (pct >= 67) return 'alto';
      if (pct >= 34) return 'moderado';
      return 'leve';
    };
    if (typeof dashboardTopDimensionScores === 'function') {
      // RDoC constructos
      if (typeof RDOC_MAP !== 'undefined' && typeof RDOC_GROUPS !== 'undefined') {
        try {
          DEF.rdoc = dashboardTopDimensionScores(RDOC_MAP, RDOC_GROUPS, 'rdoc').map(function(d){
            return { nm: d.group || '', sub: d.label || '', dir: 'up', lv: levelOf(d.pct||0) };
          });
        } catch(e){}
      }
      // HiTOP subfactores
      if (typeof HITOP_MAP !== 'undefined' && typeof HITOP_GROUPS !== 'undefined') {
        try {
          DEF.hitop = dashboardTopDimensionScores(HITOP_MAP, HITOP_GROUPS, 'hitop').map(function(d){
            return { nm: d.group || '', sub: d.label || '', dir: 'up', lv: levelOf(d.pct||0) };
          });
        } catch(e){}
      }
    }
  } catch(e){}
  return DEF;
}

