function jafloVemmfal(){
  var out = {
    'Delirium / fluctuación de conciencia': false,
    'Orientación intacta (protector)': false,
    'Extrapiramidalismo no farmacológico': false,
    'Catatonía · flexibilidad cérea (predictor #1, Blackman 2024)': false,
    'Pobreza del habla → orgánica': false,
    'Schneider 1.er rango (inserción/difusión · voces comentadoras) → primaria': false
  };
  try {
    var st = (typeof state !== 'undefined' && state) ? state : {};
    var raw = function(id){ var v = st[id] && st[id].score; return (v===null||v===undefined||v==='NE') ? null : v; };
    var num = function(id){ var v = raw(id); if(v===null) return null; var n = parseInt(v,10); return Number.isNaN(n)?null:n; };
    var spec = function(id, key){ return (st[id] && st[id].specifiers && st[id].specifiers[key]) || null; };

    // ── NC.conciencia ──
    var nc = num('NC.conciencia');
    var fluct = !!spec('NC.conciencia','F');
    // Delirium / fluctuación: conciencia alterada (!=0) o fluctuación marcada
    out['Delirium / fluctuación de conciencia'] = (nc !== null && nc !== 0) || fluct;
    // Orientación intacta (protector): conciencia preservada (0) y sin desorientación
    var desor = !!(spec('NC.conciencia','O:T') || spec('NC.conciencia','O:E') || spec('NC.conciencia','O:P'));
    out['Orientación intacta (protector)'] = (nc === 0) && !desor && !fluct;

    // ── NM: Extrapiramidalismo NO farmacológico (espontáneo) ──
    // Items con anormalidad (<=-1) y especificador de etiología espontánea/no-AP
    var pk = num('NM.parkinsonismo'); var pkE = spec('NM.parkinsonismo','pk_etiologia');
    var dk = num('NM.diskinesia');    var dkE = spec('NM.diskinesia','dk_etiologia');
    var est = num('NM.estereotipia'); var estE = spec('NM.estereotipia','est_etiologia');
    var dst = num('NM.distonia');     var dstT = spec('NM.distonia','dst_tipo');
    var akv = num('NM.acatisia');
    var trv = num('NM.tremor');
    var extra = false;
    if (pk !== null && pk <= -1 && pkE && /Espont/i.test(pkE)) extra = true;
    if (dk !== null && dk <= -1 && dkE && /Espont/i.test(dkE)) extra = true;
    if (est !== null && est <= -1 && estE && /Espont/i.test(estE)) extra = true;
    out['Extrapiramidalismo no farmacológico'] = extra;

    // ── Catatonía / flexibilidad cérea (Blackman 2024) ──
    // Proxy disponible: estereotipia de etiología 'Catatónica' (NM.estereotipia est_etiologia)
    out['Catatonía · flexibilidad cérea (predictor #1, Blackman 2024)'] =
      (est !== null && est <= -1 && estE && /Caton|Cataton/i.test(estE));

    // ── F1: Pobreza del habla → orgánica (expresividad disminuida) ──
    var f1 = num('F1.expresividad');
    out['Pobreza del habla → orgánica'] = (f1 !== null && f1 <= -1);

    // ── F4: Schneider 1.er rango (inserción/difusión/voces comentadoras) ──
    var f4 = num('F4.contenido');
    var sch = spec('F4.contenido','contenido_schneider');
    out['Schneider 1.er rango (inserción/difusión · voces comentadoras) → primaria'] =
      (f4 !== null && f4 >= 4 && sch && /Inserci|Difusi|comentando/i.test(sch));
  } catch(e){}
  return out;
}

