function jafloPrefill(id){
  // La app bMSE NO posee campos de identidad (codigo/edad/sexo/fecha/evaluador):
  // su estado ('bmse_state_v2') solo contiene scores+specifiers por dimensión.
  // Para no perder la identidad enviada por el shell, la persistimos en una key lateral
  // (NO altera la forma del estado clínico que consumen los motores de scoring).
  try {
    if (!id || typeof id !== 'object') return;
    var KEY = 'bmse_identity_v1';
    var cur = {};
    try { cur = JSON.parse(localStorage.getItem(KEY) || '{}') || {}; } catch(e){}
    ['codigo','edad','sexo','fecha','evaluador','educacion','ses','estadoCivil','etnia','ocupacion'].forEach(function(k){
      if (id[k] !== undefined && id[k] !== null && id[k] !== '') cur[k] = id[k];
    });
    localStorage.setItem(KEY, JSON.stringify(cur));
  } catch(e){}
  // Sin campos DOM que rellenar ni eventos que disparar en esta app.
}
